// components/SubscriptionStatusCard.js
// ─────────────────────────────────────────────────────────
// Ek generic card jo "mera kaunsa subscription active hai" dikhata hai.
// Ads / Ecom / Quiz — teeno "My Subscription" screens isi card ko reuse
// karte hain taaki design consistent rahe.
// ─────────────────────────────────────────────────────────
import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Image, Platform } from 'react-native';
import { Feather } from '@expo/vector-icons';

const C = {
  orange:      '#F97316',
  orangeLight: '#FFF7ED',
  white:       '#FFFFFF',
  textDark:    '#111111',
  textMid:     '#555555',
  textMuted:   '#9CA3AF',
  border:      '#E5E7EB',
  green:       '#16a34a',
  greenLight:  '#F0FDF4',
  greenMid:    '#86EFAC',
   redLight:    '#FEF2F2',
  red:         '#DC2626',
};

// ✅ NEW: SubscriptionPlansStyles wala same Roboto family — taaki card ka font
// "Choose Your Subscription Plan" heading se match kare
const FONT = {
  regular: Platform.OS === 'web' ? "'Roboto', sans-serif" : 'Roboto_400Regular',
  medium:  Platform.OS === 'web' ? "'Roboto', sans-serif" : 'Roboto_500Medium',
  bold:    Platform.OS === 'web' ? "'Roboto', sans-serif" : 'Roboto_700Bold',
};

/**
 * props:
 *  isActive        - boolean
 *  planName         - string
 *  price            - number|string
 *  countLabel       - e.g. "12 listing credits remaining" / "5 quiz attempts remaining"
 *  purchasedAt      - date string
 *  expiresAt        - date string
 *  onBuyPress       - callback for "Buy / Renew" button
 *  buyButtonLabel   - string (default "Subscribe")
 *  themeImage       - optional image source — jab diya jaata hai, card usi (purchased plan ke) color/image me dikhta hai
 *  textColor        - optional — themeImage ke saath text ka color (usually white)
 */
export default function SubscriptionStatusCard({
  isActive,
  planName,
  price,
  countLabel,
  purchasedAt,
  expiresAt,
  onBuyPress,
  buyButtonLabel = 'Subscribe',
  roles,
  duration,
  credits,
  features,
  themeImage,
  textColor,
}) {
  // ✅ jab active plan ka theme mila ho, tabhi color/image apply hoga — warna purana plain white card
    const isThemed = Boolean(isActive && themeImage) && Platform.OS === 'web';
  const dynamicText = isThemed ? (textColor || '#ffffff') : C.textDark;
  const dynamicMuted = isThemed ? 'rgba(255,255,255,0.8)' : C.textMuted;

         return (
    <View style={[styles.card, isThemed && styles.cardThemed]}>
      {isThemed ? (
                      <Image
          source={themeImage}
          resizeMode="cover"
          style={[
            StyleSheet.absoluteFillObject,
            { width: '100%', height: '100%' },
          ]}
        />
      ) : null}
      <View style={styles.headerRow}>
        <View style={[
          styles.badge,
          isActive ? (isThemed ? styles.badgeActiveThemed : styles.badgeActive) : styles.badgeInactive,
        ]}>
          <Feather
            name={isActive ? 'check-circle' : 'x-circle'}
            size={13}
            color={isActive ? (isThemed ? '#ffffff' : C.green) : C.red}
          />
          <Text style={[styles.badgeText, { color: isActive ? (isThemed ? '#ffffff' : C.green) : C.red }]}>
            {isActive ? 'Active' : 'No active subscription'}
          </Text>
        </View>
      </View>

      {isActive ? (
        <>
          <Text style={[styles.planName, { color: dynamicText }]}>{planName || 'Subscription Plan'}</Text>
          {price !== undefined && price !== null ? (
            <Text style={[styles.price, { color: dynamicMuted }]}>₹{price}</Text>
          ) : null}
          {duration ? <Text style={[styles.detailLine, { color: dynamicMuted }]}>{duration}</Text> : null}
          {credits > 0 ? <Text style={[styles.countLabel, isThemed && { color: '#ffffff' }]}>{credits} credits included</Text> : null}
          {countLabel ? <Text style={[styles.countLabel, isThemed && { color: '#ffffff' }]}>{countLabel}</Text> : null}
          {Array.isArray(features) && features.length > 0 ? (
            <View style={styles.benefitsWrap}>
              <Text style={[styles.metaLabel, { color: dynamicMuted }]}>Benefits</Text>
              {features.filter(Boolean).map((feature, index) => (
                <View key={`${feature}-${index}`} style={styles.benefitRow}>
                  <Feather name="check" size={13} color={isThemed ? '#ffffff' : C.green} />
                  <Text style={[styles.benefitText, { color: dynamicText }]}>{feature}</Text>
                </View>
              ))}
            </View>
          ) : null}
          {Array.isArray(roles) && roles.length > 0 ? (
            <View style={styles.rolesWrap}>
              <Text style={[styles.metaLabel, { color: dynamicMuted }]}>Roles</Text>
              <View style={styles.rolesRow}>
                {roles.map((r, i) => (
                  <View key={`${r}-${i}`} style={[styles.roleChip, isThemed && styles.roleChipThemed]}>
                    <Text style={[styles.roleChipText, { color: isThemed ? '#ffffff' : C.textDark }]}>{r}</Text>
                  </View>
                ))}
              </View>
            </View>
          ) : null}

          <View style={styles.metaRow}>
            {purchasedAt ? (
              <View style={styles.metaItem}>
                <Text style={[styles.metaLabel, { color: dynamicMuted }]}>Purchased</Text>
                <Text style={[styles.metaValue, { color: dynamicText }]}>{purchasedAt}</Text>
              </View>
            ) : null}
            {expiresAt ? (
              <View style={styles.metaItem}>
                <Text style={[styles.metaLabel, { color: dynamicMuted }]}>Expires</Text>
                <Text style={[styles.metaValue, { color: dynamicText }]}>{expiresAt}</Text>
              </View>
            ) : null}
          </View>
        </>
      ) : (
        <Text style={styles.emptyText}>
          You don&apos;t have an active subscription right now. Subscribe to unlock this feature.
        </Text>
      )}

      {onBuyPress ? (
        <TouchableOpacity style={styles.buyBtn} onPress={onBuyPress} activeOpacity={0.85}>
<Feather name="zap" size={15} color="#111111" />
          <Text style={styles.buyBtnText}>{isActive ? 'Renew / Change Plan' : buyButtonLabel}</Text>
        </TouchableOpacity>
      ) : null}
      </View>
  );
}

const styles = StyleSheet.create({
 card: {
    width: '100%',
    maxWidth: 480,
    backgroundColor: C.white,
    borderRadius: 14,
    padding: 14,
    borderWidth: 1,
    borderColor: C.border,
    position: 'relative',
    overflow: 'hidden',
  },
  cardThemed: {
    borderWidth: 0,
  },
  headerRow: { flexDirection: 'row', marginBottom: 12 },
  badge: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
    paddingHorizontal: 10,
    paddingVertical: 1,
    borderRadius: 999,
  },
  badgeActive: { backgroundColor: C.greenLight, borderWidth: 1, borderColor: C.greenMid },
  badgeActiveThemed: { backgroundColor: 'rgba(255,255,255,0.22)', borderWidth: 1, borderColor: 'rgba(255,255,255,0.4)' },
  badgeInactive: { backgroundColor: C.redLight, borderWidth: 1, borderColor: '#FCA5A5' },
  badgeText: { fontSize: 12, fontWeight: '700', fontFamily: FONT.medium },

  planName: { fontSize: 20, fontWeight: '600', color: C.textDark, marginBottom: 2, fontFamily: FONT.medium },
  price: { fontSize: 14, color: C.textMid, marginBottom: 6, fontFamily: FONT.regular },
  detailLine: { fontSize: 13, marginBottom: 6, fontFamily: FONT.regular },
  countLabel: { fontSize: 13, color: C.green, fontWeight: '600', marginBottom: 10, fontFamily: FONT.medium },
  benefitsWrap: { marginBottom: 10 },
  benefitRow: { flexDirection: 'row', alignItems: 'center', gap: 6, marginTop: 5 },
  benefitText: { flex: 1, fontSize: 13, lineHeight: 18, fontFamily: FONT.regular },

   rolesWrap: { marginBottom: 10 },
  rolesRow: { flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginTop: 4 },
  roleChip: { paddingHorizontal: 10, paddingVertical: 4, borderRadius: 999, backgroundColor: C.orangeLight, borderWidth: 1, borderColor: C.border },
  roleChipThemed: { backgroundColor: 'rgba(255,255,255,0.2)', borderColor: 'rgba(255,255,255,0.4)' },
  roleChipText: { fontSize: 12, fontWeight: '600', fontFamily: FONT.medium },
  metaRow: { flexDirection: 'row', gap: 24, marginTop: 4 },
  metaItem: {},
  metaLabel: { fontSize: 11, color: C.textMuted, textTransform: 'uppercase', letterSpacing: 0.5, fontFamily: FONT.regular },
  metaValue: { fontSize: 13, color: C.textDark, fontWeight: '600', marginTop: 2, fontFamily: FONT.medium },

  emptyText: { fontSize: 13, color: C.textMuted, lineHeight: 19, marginBottom: 4, fontFamily: FONT.regular },

  buyBtn: {
    marginTop: 12,
backgroundColor: '#FFFFFF',
    borderWidth: 1,
    borderColor: '#E5E7EB',
    borderRadius: 10,
    paddingVertical: 11,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 8,
  },
buyBtnText: { color: '#111111', fontSize: 14, fontWeight: '700' },
});