export default function TalukaSelectScreen({ navigation, route }) {
  useFonts({ Roboto_400Regular, Roboto_500Medium, Roboto_700Bold });
  const { login } = useAuth();
  const { showPopup } = useToast();
  const { selectedState, selectedDistrict, fromPremium, needsCreateUser, needsLogin } = route.params || {};

  const [taluka, setTaluka] = useState('');
  const [talukaModal, setTalukaModal] = useState(false);
  const allowLeaveRef = useRef(false);
  const registrationJustCompleted = !fromPremium;

  useEffect(() => {
    const unsubscribe = navigation.addListener('beforeRemove', (e) => {
      if (allowLeaveRef.current) return;
      const targetRoute = e.data.action.payload?.name;
      if (targetRoute === 'Home') return;
      e.preventDefault();
    });
    return unsubscribe;
  }, [navigation]);

  const handleClose = () => {
    allowLeaveRef.current = true;
    navigation.replace('DistrictSelect', {
      selectedState, fromPremium, needsCreateUser, preselectedDistrict: selectedDistrict,
    });
  };

  const talukaList = selectedDistrict ? getTalukas(selectedState, selectedDistrict) : [];

    const goToHome = (userName) => {
    navigation.replace('Home', {
      fromRegistration: true,
      registrationJustCompleted,
      userName: userName || 'User',
    });
  };

  const goToVillageSelect = (talukaValue) => {
    navigation.replace('VillageSelect', {
      selectedState,
      selectedDistrict,
      selectedTaluka: talukaValue,
      fromPremium,
      needsCreateUser: false, // account/taluka already saved neeche — VillageSelect sirf update karega
      needsLogin: !!needsCreateUser || !!needsLogin, // login() Village ke end me hoga
    });
  };

  // Registration (verified email OTP ke saath) Register screen par hi server par ho chuki hoti hai.
  // Yahan sirf location server par update hoti hai.
  const syncRegistrationLocation = async (talukaValue = '') => {
    try {
      const stateResult = await AuthAPI.updateState({
        state: selectedState,
        district: selectedDistrict,
        taluka: talukaValue,
      });
      if (!stateResult.ok) console.warn('[TalukaSelect] State API failed:', stateResult.message);
    } catch (error) {
      console.warn('[TalukaSelect] API sync failed:', error);
    }
  };


  const handleComplete = async () => {
        console.log('PENDING AT TALUKA:', await UserStore.getPendingRegistration(), 'needsCreateUser:', needsCreateUser);
    if (!taluka.trim()) {
      showPopup('Please select or enter your taluka', 'error');
      return;
    }
    const talukaValue = taluka.trim();

    if (needsCreateUser) {
      const pending = await UserStore.getPendingRegistration();
      if (!pending?.email) {
        showPopup('Registration data not found. Please register again.', 'error');
        allowLeaveRef.current = true;
        navigation.replace('Register');
        return;
      }

           const created = await UserStore.saveUser({
        name: pending.name, mobile: pending.mobile, email: pending.email,
        referral_code_used: pending.referral_code_used || null,
        password: pending.password, state: selectedState,
        district: selectedDistrict, taluka: talukaValue,
        profile_image: pending.profile_image || '',
        bio: pending.bio || '',
      });

      if (created && !created.ok) {
        // Account server par ban chuka hai (Register screen par) — sirf local copy save nahi hui.
        // Login karte hi profile server se sync ho jaati hai.
        await UserStore.clearPendingRegistration();
        allowLeaveRef.current = true;
        showPopup('Your account has been created. Please sign in to continue.', 'success');
        navigation.replace('Login');
        return;
      }

      await UserStore.setCurrentUser(pending.email);
      // ✅ login() yahan nahi — Village screen ke end me hoga, warna VillageSelect navigation fail hota hai
          await UserStore.completeLocationSetup(pending.email, selectedState, selectedDistrict, talukaValue);
      await UserStore.clearPendingRegistration();

      syncRegistrationLocation(talukaValue);

      goToVillageSelect(talukaValue);
      return;
    }
    const user = await UserStore.getCurrentUser();
    if (!user) { allowLeaveRef.current = true; navigation.replace('Login'); return; }

    const result = await UserStore.completeLocationSetup(user.email, selectedState, selectedDistrict, talukaValue);
    if (!result) { showPopup('Failed to save location. Please try again.', 'error'); return; }
    // API update
      AuthAPI.updateState({
      state:    selectedState,
      district: selectedDistrict,
      taluka:   talukaValue,
    }).catch(() => {});

    goToVillageSelect(talukaValue);
  };

  const handleSkip = async () => {
    if (needsCreateUser) {
      const pending = await UserStore.getPendingRegistration();
      if (!pending?.email) {
        showPopup('Registration data not found. Please register again.', 'error');
        allowLeaveRef.current = true;
        navigation.replace('Register');
        return;
      }

              const created = await UserStore.saveUser({
        name: pending.name, mobile: pending.mobile, email: pending.email,
        referral_code_used: pending.referral_code_used || null,
        password: pending.password, state: selectedState,
        district: selectedDistrict, taluka: '',
        profile_image: pending.profile_image || '',
        bio: pending.bio || '',
      });
      if (created && !created.ok) {
        // Account server par ban chuka hai (Register screen par) — sirf local copy save nahi hui.
        // Login karte hi profile server se sync ho jaati hai.
        await UserStore.clearPendingRegistration();
        allowLeaveRef.current = true;
        showPopup('Your account has been created. Please sign in to continue.', 'success');
        navigation.replace('Login');
        return;
      }

      await UserStore.setCurrentUser(pending.email);
      login();
      await UserStore.completeLocationSetup(pending.email, selectedState, selectedDistrict, '');
      await UserStore.clearPendingRegistration();

      syncRegistrationLocation('');

      goToHome(pending.name);
      return;
    }

    const user = await UserStore.getCurrentUser();
    if (!user) { allowLeaveRef.current = true; navigation.replace('Login'); return; }

    await UserStore.completeLocationSetup(user.email, selectedState, selectedDistrict, '');
    if (needsLogin) login();
    goToHome(user.name);
  };

  return (
    <SafeAreaView style={{ flex: 1 }} edges={[]}>
    <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
      <ImageBackground source={require('../assets/images/profile-red.png')} resizeMode="cover" style={styles.root}>
        <View style={[styles.glow, styles.glowTop]} />
        <View style={[styles.glow, styles.glowBottom]} />

        <ScrollView
          contentContainerStyle={styles.formScroll}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
          bounces={false}
        >
          <View style={styles.formContainer}>
            {/* Back Button */}
            <TouchableOpacity
              style={[styles.closeButton, { width: 'auto', paddingHorizontal: 10 }]}
              onPress={handleClose}
              activeOpacity={0.7}
            >
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                <Ionicons name="arrow-back" size={18} color="#ffffff" />
                <Text style={{ color: '#ffffff', fontWeight: '800', fontSize: 13, fontFamily: Platform.OS === 'web' ? "'Roboto', sans-serif" : 'Roboto_700Bold' }}>Back</Text>
              </View>
            </TouchableOpacity>

            <View style={styles.topAccent} />

            {/* Header — label + title + state/district info, no logo/icon */}
            <View style={styles.headerBlock}>
              <Text style={styles.welcomeBack}>Setup Location</Text>
              <Text style={styles.formTitle}>Select Your Taluka</Text>
              {(selectedState || selectedDistrict) && (
                <Text style={localStyles.locationInfo}>
                  {[selectedState, selectedDistrict].filter(Boolean).join(' › ')}
                </Text>
              )}
            </View>

            {talukaList.length > 0 ? (
              <>
                <View style={styles.inputGroup}>
                  <Text style={styles.inputLabel}>
                    Taluka <Text style={styles.required}>*</Text>
                  </Text>
                  <TouchableOpacity
                    style={styles.inputWrap}
                    onPress={() => setTalukaModal(true)}
                    activeOpacity={0.8}
                  >
                    <Ionicons name="map-outline" size={16} color="#a09890" />
                    <Text style={[styles.input, !taluka && { color: '#b0a898' }]}>
                      {taluka || 'Select your taluka'}
                    </Text>
                    <Ionicons name="chevron-down-outline" size={16} color="#a09890" />
                  </TouchableOpacity>
                </View>

                <TouchableOpacity
                  style={[styles.submitBtn, !taluka && styles.submitBtnDisabled]}
                  onPress={handleComplete}
                  disabled={!taluka}
                >
                  <LinearGradient colors={['#ffffff', '#f8fafc', '#f1f5f9']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.loginButtonGradient}>
                    <Text style={styles.submitBtnText}>Complete Setup</Text>
                    <Ionicons name="checkmark" size={18} color="#B91C1C" />
                  </LinearGradient>
                </TouchableOpacity>
              </>
            ) : (
              <>
                <View style={styles.inputGroup}>
                  <Text style={styles.inputLabel}>
                    Taluka <Text style={styles.required}>*</Text>
                  </Text>
                  <View style={styles.inputWrap}>
                    <Ionicons name="map-outline" size={16} color="#a09890" />
                    <TextInput
                      style={styles.input}
                      placeholder="Enter your taluka"
                      placeholderTextColor="#b0a898"
                      value={taluka}
                      onChangeText={setTaluka}
                    />
                  </View>
                </View>

                <TouchableOpacity
                  style={[styles.submitBtn, !taluka.trim() && styles.submitBtnDisabled]}
                  onPress={handleComplete}
                  disabled={!taluka.trim()}
                >
                  <LinearGradient colors={['#ffffff', '#f8fafc', '#f1f5f9']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.loginButtonGradient}>
                    <Text style={styles.submitBtnText}>Complete Setup</Text>
                    <Ionicons name="checkmark" size={18} color="#B91C1C" />
                  </LinearGradient>
                </TouchableOpacity>
              </>
            )}

            {/* Skip Button */}
            <TouchableOpacity style={localStyles.skipBtn} onPress={handleSkip} activeOpacity={0.75}>
              <Text style={localStyles.skipBtnText}>Skip for now</Text>
            </TouchableOpacity>
          </View>
        </ScrollView>

        {talukaList.length > 0 && (
          <DropdownModal
            visible={talukaModal}
            title="Select Taluka"
            items={talukaList}
            selected={taluka}
            onSelect={setTaluka}
            onClose={() => setTalukaModal(false)}
          />
        )}
      </ImageBackground>
    </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const localStyles = StyleSheet.create({
  locationInfo: {
    marginTop: 4,
    fontSize: 12,
    color: '#a09890',
    fontWeight: '600',
    letterSpacing: 0.2,
  },
  skipBtn: {
    marginTop: 12,
    alignItems: 'center',
    paddingVertical: 10,
  },
  skipBtnText: {
    color: '#a09890',
    fontSize: 13,
    fontWeight: '600',
  },
});
